    imageHint: "Mai Po Nature Reserve wetlands with boardwalk",
    descriptionAdvanced: {
      de: "Das Mai Po Naturschutzgebiet im Nordwesten Hongkongs ist ein Paradies für Vogelbeobachter und Naturfreunde. Seit seiner offiziellen Gründung im Jahr 1983 wird das Gebiet vom WWF Hongkong verwaltet und bildet das Herzstück des Ramsar-Schutzgebiets Mai Po Inner Deep Bay. Die weiten Schlammflächen, Mangrovenwälder und traditionellen Fischteiche (Gei Wai) bieten jährlich über 60.000 Zugvögeln, darunter der seltenen Schwarzgesichtlöffler, einen lebensnotwendigen Rückzugsort auf ihrer Reise entlang der ostasiatisch-australasischen Flugroute. Insgesamt wurden hier bereits mehr als 400 verschiedene Vogelarten gesichtet. Besucher können das Gebiet auf fest angelegten Wegen und durch Beobachtungshütten erkunden, wobei der Zugang zum Schutz der empfindlichen Ökosysteme streng reglementiert ist. Mai Po zeigt eindrucksvoll, dass selbst in einer Metropole wie Hongkong Raum für unberührte Natur und den Schutz der globalen Artenvielfalt besteht.",
      hu: "A Hongkong északnyugati részén elterülő Mai Po Természetvédelmi Terület a világ egyik legjelentősebb vizes élőhelye és a madármegfigyelők valóságos paradicsoma. Az 1983 óta a WWF Hong Kong által kezelt terület központi része a nemzetközi jelentőségű Ramsari területeknek. A mocsárvidék, a kiterjedt mangroveerdők és a hagyományos halastavak (Gei Wai) évente több mint 60 000 vonuló madárnak, köztük a veszélyeztetett fekete arcú kanalasgémnek nyújtanak pihenőhelyet az észak-ázsiai vonulási útvonalon. Összesen több mint 400 madárfajt regisztráltak itt, ami jól mutatja a terület biológiai sokféleségét. A látogatók kijelölt ösvényeken és megfigyelőtornyokon keresztül fedezhetik fel az ökoszisztémát, miközben a szigorú belépési szabályok biztosítják a természet nyugalmát. Mai Po ékes bizonyítéka annak, hogy egy világváros közvetlen szomszédságában is megőrizhető az érintetlen természet.",
      ro: "Rezervația Naturală Mai Po, situată în colțul de nord-vest al Hong Kong-ului, este un sanctuar ecologic de importanță mondială pentru observarea păsărilor. Gestionată de WWF Hong Kong încă de la înființarea sa în 1983, rezervația face parte integrantă dintr-un sit Ramsar protejat internațional. Peisajul este compus din mlaștini, păduri de mangrove și iazuri tradiționale de creveți cunoscute sub numele de „Gei Wai”, care oferă hrană și adăpost pentru peste 60.000 de păsări migratoare în fiecare an, inclusiv pentru specii rare precum lopătarul cu fețetă neagră. Cu peste 400 de specii de păsări înregistrate, Mai Po este un punct critic pe ruta de migrație Asia de Est-Australasia. Vizitatorii pot explora zona prin trasee special amenajate și observatoare, învățând despre fragilitatea acestui ecosistem umed într-o regiune marcată de o urbanizare extrem de intensă.",
      en: "The Mai Po Nature Reserve in northwestern Hong Kong is a world-class wetland sanctuary and a cornerstone of regional conservation efforts. Managed by WWF Hong Kong since 1983, the reserve is part of a larger Ramsar site recognized for its international importance. Its complex mosaic of mudflats, mangrove forests, and traditional shrimp ponds, called \"Gei Wai,\" serves as a vital refueling station for over 60,000 migratory birds annually along the East Asian-Australasian Flyway. Birdwatchers can spot some of the more than 400 recorded species here, including the endangered black-faced spoonbill. Access to the reserve is carefully controlled to minimize disturbance to the wildlife, allowing visitors to experience the serene beauty of the wetlands through guided tours and specialized hides, proving that biodiversity can thrive even on the doorstep of a global financial hub.",
      es: "La Reserva Natural de Mai Po se encuentra en el noroeste de los Nuevos Territorios y es un humedal de importancia internacional. Fue designada como reserva natural en 1980 y abarca 1.500 hectáreas de manglares, llanuras intermareales y estanques de peces. Es un lugar de descanso crucial para las aves migratorias, incluido el espátula menor, especie en peligro. La reserva es gestionada por WWF Hong Kong. Los visitantes pueden observar las aves desde pasarelas elevadas. Hay un centro de visitantes con exposiciones. Mai Po es sitio Ramsar desde 1995.",
      pt: "A Reserva Natural de Mai Po situa-se no noroeste dos Novos Territórios e é uma zona húmida de importância internacional. Foi designada como reserva natural em 1980 e abrange 1.500 hectares de mangais, lodaçais e tanques de peixes. É um local de descanso importante para aves migratórias, incluindo o colhereiro-de-cara-preta, que está em perigo. A reserva é gerida pela WWF Hong Kong. Os visitantes podem observar as aves em passadiços elevados. Existe um centro de visitantes com exposições. Mai Po é um sítio Ramsar desde 1995.",
      fr: "La réserve naturelle de Mai Po se situe dans le nord-ouest des Nouveaux Territoires et constitue une zone humide d'importance internationale. Déclarée réserve naturelle en 1980, elle s'étend sur 1 500 hectares de mangroves, de vasières et d'étangs de pisciculture. C'est une escale majeure pour les oiseaux migrateurs, dont la spatule mineure, espèce menacée. La réserve est gérée par le WWF Hong Kong. Les visiteurs peuvent observer les oiseaux depuis des passerelles surélevées. Un centre d'accueil propose des expositions. Mai Po est un site Ramsar depuis 1995.",
    },
