      de: "Dieser ökologische Park in Tin Shui Wai dient dem Naturschutz und der Bildung. Er zeigt die Vielfalt der lokalen Feuchtgebiets-Flora und Fauna.",
      hu: "Ez az ökológiai park Tin Shui Wai-ban a természetvédelemre és oktatásra összpontosít. Bemutatja a helyi vizes élőhelyek változatos élővilágát.",
