      es: ["Superficie de 61 hectáreas", "Inaugurado en el año 2006", "Hogar del cocodrilo Pui Pui", "Cuenta con un centro de 10.000 m²"],
      pt: ["Área de 61 hectares", "Inaugurado no ano de 2006", "Lar do crocodilo Pui Pui", "Possui um centro de 10.000 m²"],
      fr: ["Superficie de 61 hectares", "Inauguré en 2006", "Abrite le crocodile Pui Pui", "Dispose d'un centre de 10 000 m²"],
