    imageHint: "Hong Kong Zoological and Botanical Gardens fountain",
    descriptionAdvanced: {
      de: "Der Zoologische und Botanische Garten von Hongkong wurde im Jahr 1871 eröffnet und ist damit eine der ältesten Einrichtungen dieser Art weltweit. Er erstreckt sich über eine Fläche von 5,6 Hektar am Nordhang des Victoria Peak und bietet einen grünen Kontrast zu den Wolkenkratzern von Central. Der Park ist in zwei Teile gegliedert, die durch eine Unterführung verbunden sind: Der östliche Teil beherbergt hauptsächlich Volieren und Gärten, während der westliche Teil den Schwerpunkt auf Säugetiere legt. Besonders bekannt ist die Anlage für ihre erfolgreiche Zucht bedrohter Primaten, darunter Borneo-Orang-Utans und Gibbons. Botanisch interessierte Besucher finden hier über 1.000 Pflanzenarten, darunter seltene Kamelien und ein historisches Gewächshaus. Ein markantes Denkmal im Garten ist die Bronzestatue von König George VI., die an die koloniale Vergangenheit der Stadt erinnert. Der Eintritt ist kostenfrei, was den Garten zu einem beliebten Rückzugsort für Einheimische macht.",
      hu: "A Hong Kong központjában, a Victoria-csúcs északi lankáin elterülő Zoológiai és Botanikus Kert a város legrégebbi parkja, amelyet 1871-ben adtak át a közönségnek. Az 5,6 hektáros terület különleges oázis a sűrűn beépített felhőkarcolók gyűrűjében, ahol a gyarmati múlt emlékei és a modern természetvédelem találkozik. A kert egyik fő vonzereje a nemzetközileg elismert főemlősgyűjtemény, ahol többek között borneói orangutánokat, gibbonokat és tamarinokat láthatnak a látogatók. A botanikai részleg több mint ezer növényfajt mutat be, köztük ritka trópusi fákat és látványos orchideákat a pálmaházban. A park két részét egy alagút köti össze, egyik oldalán a madárházakkal és a történelmi szökőkúttal, a másikon az emlősök kifutóival. Ingyenes belépése és központi elhelyezkedése miatt a helyszín ideális pihenőhely a városnézés közben, miközben fontos szerepet tölt be a veszélyeztetett fajok megőrzésében is.",
      ro: "Deschisă oficial în anul 1871, Grădina Zoologică și Botanică din Hong Kong este una dintre cele mai vechi instituții de profil din lume, oferind un refugiu verde în inima districtului Central. Situată pe versantul nordic al faimosului Victoria Peak, grădina se întinde pe aproximativ 5,6 hectare și este divizată în două secțiuni principale legate printr-un pasaj subteran. Secțiunea estică este renumită pentru fântâna sa istorică și grădinile tematice, în timp ce secțiunea vestică se concentrează pe fauna exotică. Grădina este celebră pentru colecția sa impresionantă de primate, incluzând urangutani de Borneo și giboni, fiind implicată activ în programe de conservare a speciilor pe cale de dispariție. Din punct de vedere botanic, vizitatorii pot admira peste 1.000 de specii de plante, de la arbori seculari la exemplare rare din seră. Statuia de bronz a Regelui George al VI-lea și arhitectura pavilioanelor păstrează farmecul epocii coloniale britanice, făcând din acest loc o destinație culturală și recreativă gratuită.",
      en: "Inaugurated in 1871, the Hong Kong Zoological and Botanical Gardens is the oldest park in the territory, serving as a lush sanctuary amidst the skyscrapers of Central. Spanning 5.6 hectares on the northern slopes of Victoria Peak, the gardens are divided into eastern and western sections connected by a pedestrian tunnel. The facility is world-renowned for its primate collection, which includes Bornean orangutans, buff-cheeked gibbons, and various species of lemurs, many of which are part of international breeding programs for endangered species. Botanically, the park is home to over 1,000 plant species, featuring a historic greenhouse, a thematic herb garden, and a collection of rare camellias. Landmarks within the grounds include the 19th-century cast-iron fountain and a bronze statue of King George VI, reflecting the site's colonial heritage. As admission is free, it remains a beloved educational and recreational destination for both locals and tourists seeking a peaceful break from the urban bustle.",
      es: "Los Jardines Zoológicos y Botánicos de Hong Kong son el parque más antiguo de la ciudad, fundados en 1860. Se encuentran en el distrito Central, sobre una colina. El jardín abarca 5,6 hectáreas y alberga más de 900 especies de plantas y una pequeña colección de animales, incluyendo primates y aves. El parque es conocido por su paisajismo victoriano y su fuente. Sirve para el recreo y la educación. El acceso es gratuito. Ofrece una vista del puerto. La colección botánica incluye plantas autóctonas y exóticas.",
      pt: "Os Jardins Zoológicos e Botânicos de Hong Kong são o parque mais antigo da cidade, fundado em 1860. Estão localizados no distrito Central, numa colina. O jardim abrange 5,6 hectares e abriga mais de 900 espécies de plantas e uma pequena coleção de animais, incluindo primatas e aves. O parque é conhecido pelo seu paisagismo vitoriano e pela fonte. Serve para recreação e educação. O jardim tem acesso gratuito. Oferece uma vista para o porto. A coleção botânica inclui plantas nativas e exóticas.",
      fr: "Les jardins zoologiques et botaniques de Hong Kong sont le plus ancien parc de la ville, fondés en 1860. Ils sont situés dans le district de Central sur une colline. Le jardin s'étend sur 5,6 hectares et abrite plus de 900 espèces de plantes ainsi qu'une petite collection d'animaux, notamment des primates et des oiseaux. Le parc est connu pour son aménagement paysager victorien et sa fontaine. Il sert aux loisirs et à l'éducation. Le jardin est accessible gratuitement. Il offre une vue sur le port. La collection botanique comprend des plantes indigènes et exotiques.",
    },
