    imageHint: "Hoi Ha Wan Marine Park clear water and corals",
    descriptionAdvanced: {
      de: "Der Hoi Ha Wan Marinepark im Nordosten des Sai Kung Distrikts ist eines der kostbarsten Naturschutzgebiete Hongkongs. Das 1996 gegründete Reservat schützt eine beeindruckende biologische Vielfalt, darunter über 60 Steinkorallenarten und mehr als 120 Fischarten. Die geschützte Lage in einer tiefen Bucht sorgt für klares, ruhiges Wasser, was den Park zu einem idealen Ort für Schnorchler macht, die das bunte Unterwasserleben erkunden möchten. Besucher können zudem an geführten Touren in Glasbodenbooten teilnehmen, um die Korallenriffe zu bewundern, ohne nass zu werden. Das WWF Hong Kong Marine Life Centre vor Ort bietet Bildungsprogramme an und informiert über die ökologische Bedeutung des Meeresbodens im Südchinesischen Meer. Neben der Unterwasserwelt besticht die Umgebung durch ihre unberührte Natur, Mangrovenwälder und historische Kalköfen am Strand. Hoi Ha Wan ist ein Rückzugsort für Naturliebhaber, der zeigt, dass Hongkong neben seiner Urbanität auch spektakuläre Ökosysteme zu bieten hat, die strengen Schutz genießen.",
      hu: "A Hoi Ha Wan Tengeri Park a Sai Kung-félsziget északi részén található, és Hong Kong egyik legfontosabb természetvédelmi területe. Az 1996-ban alapított park célja a rendkívül gazdag tengeri élővilág megőrzése, különös tekintettel az itt található több mint 60 kőkorall-fajra. Az öböl védett elhelyezkedése miatt a víz általában tiszta és nyugodt, ami kiváló feltételeket biztosít a sznorkelezéshez és a víz alatti megfigyelésekhez. A látogatók a WWF által üzemeltetett látogatóközpontban mélyíthetik el ismereteiket a tengerbiológiáról, vagy üvegfenekű hajókról csodálhatják meg a korallzátonyok színpompás világát. A park part menti sávjában mangroveerdők és régi mészégető kemencék maradványai is felfedezhetők, amelyek a terület korábbi gazdasági tevékenységéről tanúskodnak. Hoi Ha Wan tökéletes menekülést kínál a városi nyüzsgés elől, emlékeztetve arra, hogy Hong Kong tengeri ökoszisztémája mennyire törékeny és értékes. A terület autómentes övezet, így a nyugalom és a természet közelsége garantált minden látogató számára.",
      ro: "Parcul Marin Hoi Ha Wan, situat în partea de nord a peninsulei Sai Kung, este una dintre cele mai prețioase rezervații naturale din Hong Kong. Înființat în 1996, parcul a fost creat special pentru a proteja ecosistemul marin bogat, care include peste 60 de specii de corali duri și o diversitate impresionantă de pești tropicali. Datorită poziției sale într-un golf adânc și ferit, apele sunt surprinzător de limpezi, oferind condiții excelente pentru snorkeling și scufundări. Vizitatorii pot explora viața marină și prin intermediul bărcilor cu fund de sticlă, care permit observarea recifelor fără a deranja mediul fragil. Centrul WWF din cadrul parcului joacă un rol vital în educația ecologică, oferind informații despre importanța conservării oceanelor. Pe lângă bogăția subacvatică, zona Hoi Ha găzduiește păduri de mangrove și vestigii istorice, cum ar fi cuptoarele de var abandonate de pe mal. Este o destinație ecoturistică de top, demonstrând angajamentul regiunii pentru protejarea biodiversității în ciuda expansiunii urbane masive din restul metropolei.",
      en: "Hoi Ha Wan Marine Park, nestled in a sheltered bay on the northern coast of Sai Kung Peninsula, is a sanctuary for some of Hong Kong's most diverse marine life. Established in 1996 as one of the territory's first marine parks, it protects a thriving coral community consisting of over 60 species, which accounts for a vast majority of the coral types found in the region. The park's clear, shallow waters make it a premier destination for snorkeling and kayaking, allowing nature enthusiasts to witness colorful reef fish and invertebrates in their natural habitat. For those who prefer to stay dry, the WWF Marine Life Centre offers educational glass-bottom boat tours and interactive exhibits on marine conservation. The surrounding landscape is equally captivating, featuring lush mangroves and historical lime kilns that date back to the early local industries. Accessible primarily by public transport or on foot to minimize environmental impact, Hoi Ha Wan provides a peaceful escape where the focus remains entirely on ecological preservation and sustainable tourism.",
      es: "El Hoi Ha Wan Marine Park se encuentra en el noreste de los Nuevos Territorios y fue establecido en 1996. Abarca 260 hectáreas de superficie marina con arrecifes de coral, praderas marinas y manglares. El parque es una zona protegida vital para la vida marina, incluyendo más de 60 especies de coral y numerosos peces. Ofrece oportunidades para el snorkel y el buceo. El parque es gestionado por el gobierno y cuenta con una pasarela para visitantes y programas educativos. La región también es conocida por su geología y promueve el turismo sostenible.",
      pt: "O Hoi Ha Wan Marine Park está localizado no nordeste dos Novos Territórios e foi estabelecido em 1996. Abrange 260 hectares de área marinha com recifes de coral, prados de ervas marinhas e manguezais. O parque é uma importante área protegida para a vida marinha, incluindo mais de 60 espécies de coral e muitos peixes. Oferece oportunidades para snorkeling e mergulho. O parque é gerido pelo governo. Existe um passadiço para visitantes e programas educacionais. A região também é conhecida pela sua geologia e promove o turismo sustentável.",
      fr: "Le parc marin de Hoi Ha Wan est situé au nord-est des Nouveaux Territoires et a été créé en 1996. Il couvre 260 hectares de zone marine comprenant des récifs coralliens, des herbiers marins et des mangroves. Le parc est une zone protégée majeure pour la vie marine, avec plus de 60 espèces de coraux et de nombreux poissons. Il offre des possibilités de plongée avec tuba et de plongée sous-marine. Géré par le gouvernement, le parc dispose d'une passerelle pour les visiteurs et de programmes éducatifs. La région est également réputée pour sa géologie et encourage le tourisme durable.",
    },
