      en: ["Area: 460 hectares", "Designated reserve in 1977", "Over 100 bird species", "Secondary forest", "Camphor trees and bamboo", "Research and education"],
      es: ["Superficie: 460 hectáreas", "Estado de protección desde 1977", "Más de 100 especies de aves", "Bosque secundario", "Alcanforeros y bambú", "Investigación y educación"],
