      de: "Der Park im Nordosten umfasst malerische Inseln und Küstenabschnitte. Er ist bekannt für seine ruhige Atmosphäre und Wanderwege.",
      hu: "Az északkeleti park festői szigeteket és part menti szakaszokat foglal magában. Nyugodt légköréről és túraútvonalairól ismert.",
      ro: "Parcul din nord-est include insule pitorești și secțiuni de coastă. Este cunoscut pentru atmosfera liniștită și traseele sale.",
