      pt: ["Altura do pico: 495 metros", "Fundado no ano de 1977", "Símbolo do espírito de Hong Kong", "Inclui a Amah Rock"],
      fr: ["Altitude du sommet : 495 mètres", "Fondé en 1977", "Symbole de l'esprit de Hong Kong", "Comprend l'Amah Rock"],
