    imageHint: "Lion Rock peak overlooking the city",
    descriptionAdvanced: {
      de: "Der Lion Rock Country Park erstreckt sich über die Hügelkette zwischen Kowloon und den New Territories und ist eines der bekanntesten Naherholungsgebiete Hongkongs. Sein Herzstück ist der namensgebende Lion Rock, ein 495 Meter hoher Bergrücken, dessen Silhouette verblüffend einem kauernden Löwen ähnelt. Für die Menschen in Hongkong ist dieser Berg weit mehr als nur ein Naturdenkmal; der 'Lion Rock Spirit' steht symbolisch für die Widerstandsfähigkeit, den Fleiß und den Zusammenhalt der Stadtbewohner. Der Park wurde 1977 offiziell gegründet und bietet ein gut ausgebautes Wegenetz, das Wanderer zu spektakulären Aussichtspunkten führt. Von der Spitze aus bietet sich ein unvergleichliches Panorama über das dicht besiedelte Kowloon bis hin zum Victoria Harbour und Hongkong Island. Ein weiteres Highlight im Park ist der Amah Rock, eine Felsformation, die einer Frau mit einem Kind auf dem Rücken ähnelt und Gegenstand lokaler Legenden ist. Trotz der Nähe zum Großstadtdschungel ist der Park ein wichtiger Lebensraum für Rhesusaffen und zahlreiche Vogelarten.",
      hu: "A Lion Rock Vidéki Park Hongkong egyik legikonikusabb természetvédelmi területe, amely a nyüzsgő Kowloon és az Új Területek határán húzódik. A park névadója a 495 méter magas Lion Rock, amelynek gerince egy fekvő oroszlán sziluettjét formázza. A hegy nem csupán látványos geológiai képződmény, hanem a hongkongi identitás fontos része is: a 'Lion Rock szellem' a helyiek szorgalmát, kitartását és az összefogás erejét jelképezi. Az 1977-ben alapított park változatos túraútvonalai között mindenki megtalálja a számítását, a csúcsra vezető ösvényekről pedig lélegzetelállító panoráma nyílik a felhőkarcolókkal teli városra és a Viktória-kikötőre. A park területén található az Amah Rock is, egy különleges sziklaalakzat, amelyhez egy megható legenda fűződik egy hűséges feleségről. A sűrű növényzet számos vadon élő állatnak, többek között rhesusmajmoknak és különleges madárfajoknak ad otthont, így a látogatók valódi természeti menedéket találnak a metropolisz közvetlen közelében.",
      ro: "Parcul Lion Rock este unul dintre cele mai emblematice spații verzi din Hong Kong, situat pe crestele muntoase care despart Kowloon de Noile Teritorii. Punctul central al parcului este stânca Lion Rock, aflată la o altitudine de 495 de metri, a cărei formă amintește în mod frapant de un leu care veghează asupra orașului. Dincolo de frumusețea sa naturală, muntele are o valoare culturală imensă, 'spiritul Lion Rock' simbolizând reziliența și unitatea locuitorilor din Hong Kong în perioadele de transformare socială. Înființat oficial în 1977, parcul oferă trasee de drumeție bine întreținute care duc spre puncte de observație de unde se poate vedea întreaga peninsulă Kowloon, Portul Victoria și insula Hong Kong. O altă atracție notabilă este Amah Rock, o formațiune stâncoasă legendară care seamănă cu o femeie purtând un copil în spate. Parcul este și un refugiu pentru biodiversitate, fiind habitatul multor maimuțe rhesus și specii de păsări tropicale, oferind un contrast fascinant între natura sălbatică și jungla de asfalt a metropolei.",
      en: "Lion Rock Country Park is one of Hong Kong's most culturally significant natural areas, spanning the mountain range between Kowloon and the New Territories. The park's centerpiece is the 495-meter-high Lion Rock, a granite peak whose silhouette bears a striking resemblance to a crouching lion. To the people of Hong Kong, this mountain is a powerful symbol of identity; the 'Lion Rock Spirit' represents the hard work, perseverance, and solidarity that built the modern city. Established in 1977, the park features a network of hiking trails, the most famous of which climbs to the 'lion's head,' offering an unparalleled panoramic view of the dense skyscrapers of Kowloon, Victoria Harbour, and Hong Kong Island. Another landmark within the park is Amah Rock, a distinctive formation linked to a poignant local legend of a faithful wife. Despite its proximity to the urban center, the park is a thriving ecosystem, home to troops of rhesus macaques and various birds of prey, providing a vital green escape for city dwellers and tourists alike.",
      es: "El Lion Rock Country Park se encuentra en el norte de Kowloon y abarca 557 hectáreas. Se estableció en 1977. Debe su nombre a la roca con forma de león, un emblema local. El parque ofrece senderos con vistas a Kowloon y a la isla de Hong Kong. El punto más alto es el propio Lion Rock, con 495 metros. Su geología consiste en toba volcánica. El parque es un destino de senderismo popular y alberga monos y aves. Los visitantes pueden disfrutar de las vistas.",
      pt: "O Lion Rock Country Park está localizado no norte de Kowloon e abrange 557 hectares. Foi estabelecido em 1977. É nomeado em homenagem à rocha semelhante a um leão, um marco da cidade. O parque oferece trilhas com vista para Kowloon e Hong Kong Island. O ponto mais alto é o próprio Lion Rock com 495 metros. A geologia consiste em tufo vulcânico. O parque é um destino popular para caminhadas. Abriga macacos e aves. Os visitantes podem desfrutar da vista.",
      fr: "Le Lion Rock Country Park est situé au nord de Kowloon et s'étend sur 557 hectares. Créé en 1977, il tire son nom du rocher en forme de lion, véritable emblème de la ville. Le parc propose des sentiers de randonnée offrant une vue sur Kowloon et l'île de Hong Kong. Le point culminant est le Lion Rock lui-même, à 495 mètres. Sa géologie est composée de tuf volcanique. Destination de randonnée prisée, le parc abrite des singes et des oiseaux. Les visiteurs peuvent y admirer le panorama.",
    },
