      pt: ["Área: 339 hectares", "Fundação: 1977", "População de macacos", "Golden Hill: 369 m", "Floresta secundária", "Reservatório"],
      fr: ["Superficie : 339 hectares", "Fondation : 1977", "Population de macaques", "Golden Hill : 369 m", "Forêt secondaire", "Réservoir"],
