    facts: {
      de: ["Gegründet im Jahr 1977", "Erster Rollstuhl-Wanderweg", "Zwei Aberdeen-Stauseen", "Beliebt für Grillfeste"],
      hu: ["1977-ben alapították", "Első kerekesszékes túraútvonal", "Két Aberdeen-víztározó", "Népszerű grillezőhelyek"],
      ro: ["Fondat în anul 1977", "Primul traseu pt scaun cu rotile", "Două rezervoare Aberdeen", "Popular pentru grătare"],
      en: ["Established in 1977", "First wheelchair-accessible trail", "Home to two reservoirs", "Popular spot for barbecues"],
      es: ["Fundado en el año 1977", "Primer sendero para sillas de ruedas", "Dos embalses de Aberdeen", "Popular para barbacoas"],
      pt: ["Fundado no ano de 1977", "Primeiro trilho para cadeiras de rodas", "Duas albufeiras de Aberdeen", "Popular para churrascos"],
      fr: ["Fondé en 1977", "Premier sentier pour fauteuils roulants", "Deux réservoirs d'Aberdeen", "Apprécié pour les barbecues"],
    },
    imageHint: "Aberdeen Reservoir surrounded by greenery",
    descriptionAdvanced: {
      de: "Der Aberdeen Country Park liegt an den südlichen Hängen des Victoria Peak auf der Insel Hongkong und bietet eine friedliche Flucht aus der urbanen Hektik. Gegründet im Jahr 1977, gehört er zu den ältesten Parks der Region und ist besonders für seine beiden Stauseen, den Upper und Lower Aberdeen Reservoir, bekannt. Diese Wasserflächen sind von dichten Wäldern umgeben, die eine Vielzahl von Vogelarten beherbergen. Ein besonderes Merkmal des Parks ist der erste rollstuhlgerechte Wanderweg Hongkongs, was ihn zu einem Vorreiter in Sachen Inklusion macht. Die gut ausgebauten Pfade führen durch üppige Vegetation und bieten immer wieder Ausblicke auf das Hafenviertel von Aberdeen. Der Park ist zudem ein äußerst beliebter Ort für Familien, die die zahlreichen Grillplätze und Picknickareale nutzen. Ob für eine anspruchsvolle Wanderung oder einen entspannten Spaziergang am Wasser – der Aberdeen Country Park verbindet Naturerlebnis mit hervorragender Erreichbarkeit inmitten der Metropole.",
      hu: "Az Aberdeen Vidéki Park Hong Kong-sziget déli lankáin terül el, és a város egyik legkedveltebb zöld oázisa. Az 1977-ben alapított park híres két festői víztározójáról (Upper és Lower Aberdeen Reservoir), amelyeket sűrű erdők és jól karbantartott túraútvonalak vesznek körül. A terület különlegessége, hogy itt alakították ki Hong Kong első kerekesszékkel is járható túraútvonalát, így a természet élvezete mindenki számára elérhető. A park növényvilága rendkívül gazdag, a buja növényzet között számos madárfaj és apróbb vadállat talál menedéket. A kirándulók gyakran keresik fel a parkot a panoráma miatt is, hiszen több pontról rálátás nyílik Aberdeen kikötőjére és a környező szigetekre. A családok körében különösen népszerűek a kijelölt grillezőhelyek, amelyek hétvégenként élettel telnek meg. Az Aberdeen Vidéki Park kiváló példája annak, hogyan fér meg egymás mellett a modern világváros és az érintetlen természet.",
      ro: "Parcul Aberdeen, situat pe versanții sudici ai insulei Hong Kong, reprezintă un refugiu natural esențial în contrast cu densitatea urbană a metropolei. Fondat în anul 1977, parcul este renumit pentru cele două rezervoare de apă (Upper și Lower Aberdeen Reservoir), care servesc nu doar ca resurse hidrografice, ci și ca puncte focale ale peisajului forestier luxuriant. O caracteristică remarcabilă a acestui spațiu este primul traseu de drumeție din Hong Kong adaptat persoanelor cu dizabilități motorii, subliniind angajamentul regiunii față de accesibilitate. Traseele bine întreținute șerpuiesc prin păduri dese, oferind vizitatorilor șansa de a observa specii variate de păsări și fluturi. Parcul este o destinație extrem de populară pentru petrecerea timpului liber, fiind dotat cu numeroase zone pentru grătare și locuri de joacă. De pe culmile sale, se pot admira vederi parțiale asupra portului Aberdeen și a insulei Lamma în depărtare.",
      en: "Aberdeen Country Park, nestled on the southern slopes of Hong Kong Island, offers a serene escape from the high-octane energy of the city. Established in 1977, it is one of the region's oldest designated country parks and is centered around the Upper and Lower Aberdeen Reservoirs. These tranquil bodies of water are flanked by dense broadleaf woodlands that provide a sanctuary for various bird species, including the black kite. A pioneering feature of the park is Hong Kong’s first wheelchair-accessible nature trail, making the beauty of the outdoors inclusive for all visitors. The park's extensive network of trails, such as the Lady Clementi's Ride, winds through lush vegetation and offers glimpses of the bustling Aberdeen harbor below. With its numerous well-equipped barbecue sites and picnic areas, the park is a favorite weekend destination for local families, seamlessly integrating natural preservation with public recreation.",
      es: "El Parque Rural de Aberdeen se encuentra al suroeste de la isla de Hong Kong y abarca 423 hectáreas. Establecido en 1977, el parque ofrece senderos a través de valles boscosos y a lo largo de la costa. Alberga el embalse de Aberdeen y el High West. La vegetación incluye laureles y alcanforeros, siendo un lugar destacado para la observación de aves. Los visitantes pueden acudir al mirador de High West, mientras el parque cumple la función de proteger el suministro de agua potable.",
      pt: "O Aberdeen Country Park situa-se no sudoeste da Ilha de Hong Kong e abrange 423 hectares. Foi estabelecido em 1977. O parque oferece trilhos para caminhadas através de vales arborizados e ao longo da costa. Abriga a albufeira de Aberdeen e o High West. A vegetação inclui loureiros e canforeiras. O parque é conhecido pela sua avifauna. Os visitantes podem visitar o miradouro no High West. O parque protege o abastecimento de água potável.",
      fr: "Le parc forestier d'Aberdeen est situé au sud-ouest de l'île de Hong Kong et s'étend sur 423 hectares. Créé en 1977, il propose des sentiers de randonnée à travers des vallées boisées et le long de la côte. Il abrite le réservoir d'Aberdeen et le High West. La végétation se compose de lauriers et de camphriers. Le parc est réputé pour sa faune aviaire. Les visiteurs peuvent se rendre au point de vue du High West. Le parc protège l'approvisionnement en eau potable.",
    },
