      en: ["Area: 270 hectares", "Established in 1977", "Pok Fu Lam Reservoir", "Near Victoria Peak", "Hong Kong Trail", "Water protection area"],
      es: ["Superficie: 270 hectáreas", "Fundación: 1977", "Embalse de Pok Fu Lam", "Cerca de Victoria Peak", "Ruta Hong Kong Trail", "Zona de protección hídrica"],
      pt: ["Área: 270 hectares", "Fundação: 1977", "Albufeira de Pok Fu Lam", "Perto do Victoria Peak", "Hong Kong Trail", "Zona de proteção da água"],
