    facts: {
      de: ["Fläche: 3,5 Hektar", "Eröffnet im Jahr 2006", "Verfügt über einen goldenen Pavillon", "Verbindung zum Chi Lin Nonnenkloster"],
      hu: ["Területe 3,5 hektár", "2006-ban nyitották meg", "Arany pavilon található benne", "A Chi Lin zárda mellett van"],
      ro: ["Suprafață: 3,5 hectare", "Deschisă în anul 2006", "Include un pavilion auriu", "Conectată la mănăstirea Chi Lin"],
      en: ["Area: 3.5 hectares", "Opened in 2006", "Features a Golden Pavilion", "Linked to Chi Lin Nunnery"],
      es: ["Superficie: 3,5 hectáreas", "Inaugurado en el año 2006", "Cuenta con un pabellón dorado", "Conexión con el Monasterio Chi Lin"],
      pt: ["Área: 3,5 hectares", "Inaugurado em 2006", "Possui um pavilhão dourado", "Ligação ao Convento Chi Lin"],
      fr: ["Superficie : 3,5 hectares", "Ouvert en 2006", "Possède un pavillon doré", "Relié au couvent Chi Lin"],
    },
    imageHint: "Nan Lian Garden Golden Pavilion and bridge",
    descriptionAdvanced: {
      de: "Der Nan Lian Garten ist eine 3,5 Hektar große Oase der Ruhe, die sich inmitten der Wolkenkratzer von Diamond Hill in Kowloon befindet. Seit seiner Eröffnung im Jahr 2006 beeindruckt der Garten durch seine Gestaltung im Stil der Tang-Dynastie, die auf einer harmonischen Verbindung von Wasser, Felsen, Pflanzen und Holzarchitektur basiert. Jedes Detail, von der Platzierung der Steine bis hin zum Schnitt der Bäume, folgt strengen Regeln der klassischen chinesischen Gartenkunst. Das Wahrzeichen der Anlage ist der Pavillon der Vollkommenheit, ein goldglänzendes Bauwerk, das über leuchtend rote Holzbrücken inmitten eines Seerosenteichs erreichbar ist. Durch eine Fußgängerbrücke ist der Garten mit dem angrenzenden Chi Lin Nonnenkloster verbunden. Besucher können hier in einem traditionellen Teehaus entspannen, ein vegetarisches Restaurant hinter einem künstlichen Wasserfall besuchen oder Ausstellungen von Penjing-Bäumen (Bonsai) bewundern. Der Nan Lian Garten bietet einen faszinierenden Kontrast zur Hektik Hongkongs und lädt dazu ein, in die ästhetische Welt des alten Chinas einzutauchen.",
      hu: "A Nan Lian kert egy 3,5 hektáros békesziget Kowloon felhőkarcolói között, Diamond Hill szívében. A 2006-ban megnyitott kertet aprólékos gonddal, a Tang-dinasztia stílusában alakították ki, hangsúlyozva a víz, a sziklák, a növények és a faépítmények közötti harmonikus egyensúlyt. Minden egyes elem a hagyományos kínai kertépítészet szigorú szabályait követi, így a látogató egy egyirányú útvonalon haladva festői tájak sorozatát fedezheti fel. A kert központi eleme a lenyűgöző Arany Pavilon (a Tökéletesség Pavilonja), amelyhez élénkvörös fahidat vezetnek a tavirózsákkal teli tó felett. A kertet egy gyaloghíd köti össze a szomszédos Chi Lin zárda épületegyüttesével. A látogatók élvezhetik a hagyományos teaház nyugalmát, megkóstolhatják a vízesés mögé rejtett vegetáriánus étterem fogásait, vagy megcsodálhatják a különleges bonszaj- és kőkiállításokat. A Nan Lian kert nem csupán egy közpark, hanem a Tang-kori esztétika élő múzeuma, amely vizuális és spirituális utazást kínál az ősi kínai kultúrába.",
      ro: "Situată printre zgârie-norii din zona Diamond Hill din Kowloon, Grădina Nan Lian este o oază de liniște de 3,5 hectare, ce emană o frumusețe clasică rară. Deschisă în 2006, grădina a fost proiectată meticulos în stilul dinastiei Tang, punând accent pe echilibrul armonios între apă, roci, plante și structuri din lemn. Fiecare element urmează reguli specifice ale peisagisticii tradiționale chinezești, oferind vizitatorilor o succesiune de vederi pitorești de-a lungul unui traseu circular. Elementul central este Pavilionul Perfecțiunii, o structură aurie spectaculoasă conectată prin poduri de lemn roșu aprins peste un iaz cu nuferi. Grădina este legată de Mănăstirea Chi Lin din apropiere printr-o pasarelă, formând împreună un refugiu spiritual departe de ritmul frenetic al orașului. Vizitatorii se pot bucura de o ceainărie tradițională, un restaurant vegetarian situat în spatele unei cascade și expoziții de arbori penjing (bonsai). Grădina Nan Lian nu este doar un parc public, ci un muzeu viu al esteticii Tang, oferind o călătorie vizuală și spirituală prin cultura antică chineză.",
      en: "Nestled amidst the high-rise urban landscape of Diamond Hill in Kowloon, the Nan Lian Garden is a 3.5-hectage oasis of serenity and classical beauty. Opened in 2006, the garden was meticulously designed in the style of the Tang Dynasty, emphasizing the harmonious balance between water, rocks, plants, and timber structures. Every element follows specific rules of traditional Chinese landscaping, creating a series of picturesque views as one wanders along the one-way circular path. The centerpiece of the garden is the iconic Perfection Pavilion, a stunning golden structure connected by bright red wooden bridges over a tranquil lily pond. The garden is linked to the adjacent Chi Lin Nunnery via a footbridge, and together they form a peaceful retreat from the city's frantic pace. Visitors can enjoy a traditional tea house, a vegetarian restaurant tucked behind a waterfall, and various exhibitions of penjing (bonsai) and ancient rocks. The garden serves not only as a public park but as a living museum of Tang-style aesthetics, offering a spiritual and visual journey through ancient Chinese culture.",
      es: "El Jardín Nan Lian es un jardín tradicional chino en el distrito de Diamond Hill, en Kowloon. Se inauguró en 2006 y abarca 3,5 hectáreas. El jardín sigue el estilo de la dinastía Tang y alberga un estanque de lotos de 9 niveles, un jardín Zen y una colección de bonsáis. El adyacente Monasterio Chi Lin complementa el ambiente espiritual. El jardín sirve para la educación cultural y ofrece regularmente ceremonias de té y talleres de caligrafía.",
      pt: "O Jardim Nan Lian é um jardim chinês tradicional no bairro de Diamond Hill, em Kowloon. Foi inaugurado em 2006 e estende-se por 3,5 hectares. O jardim foi concebido ao estilo da Dinastia Tang e alberga um tanque de lótus de 9 níveis, um jardim Zen e uma coleção de bonsais. O adjacente Mosteiro Chi Lin complementa o ambiente espiritual. O jardim serve para educação cultural e oferece regularmente cerimónias de chá e workshops de caligrafia.",
      fr: "Le jardin Nan Lian est un jardin chinois traditionnel situé dans le quartier de Diamond Hill, à Kowloon. Ouvert en 2006, il s'étend sur 3,5 hectares. Le jardin est conçu dans le style de la dynastie Tang et abrite un bassin de lotus à 9 niveaux, un jardin zen et une collection de bonsaïs. Le monastère Chi Lin adjacent complète l'ambiance spirituelle. Le jardin sert à l'éducation culturelle et propose régulièrement des cérémonies du thé et des ateliers de calligraphie.",
    },
