    facts: {
      de: ["Eröffnet im Jahr 1991", "Ehemalige Victoria-Kaserne", "Beherbergt ein Tee-Museum", "Umfasst künstliche Wasserfälle"],
      hu: ["1991-ben nyitották meg", "Egykori Victoria laktanya", "Teázó múzeumnak ad otthont", "Mesterséges vízesések díszítik"],
      ro: ["Deschis în anul 1991", "Fosta cazarmă Victoria", "Găzduiește un muzeu al ceaiului", "Include cascade artificiale"],
      en: ["Opened in 1991", "Site of former Victoria Barracks", "Home to Museum of Tea Ware", "Features artificial waterfalls"],
      es: ["Inaugurado en el año 1991", "Antiguo Cuartel Victoria", "Alberga un museo del té", "Incluye cascadas artificiales"],
      pt: ["Inaugurado em 1991", "Antigo Quartel Victoria", "Alberga um museu do chá", "Inclui cascatas artificiais"],
      fr: ["Ouvert en 1991", "Ancienne caserne Victoria", "Abrite un musée du thé", "Comprend des cascades artificielles"],
    },
    imageHint: "Hong Kong Park waterfalls and skyscrapers",
    descriptionAdvanced: {
      de: "Der Hongkong Park ist eine acht Hektar große Oase der Ruhe inmitten der dicht bebauten Hochhauslandschaft von Central. Er wurde 1991 auf dem Gelände der ehemaligen britischen Victoria-Kaserne eröffnet und ist ein herausragendes Beispiel für die Integration von Natur in eine moderne Stadtplanung. Eine der Hauptattraktionen ist die Edward Youde Voliere, eine der größten begehbaren Vogelhallen der Welt, die über einem künstlich angelegten Tal mit tropischem Regenwald thront. Der Park beherbergt zudem das Flagstaff House Museum of Tea Ware, das in einem historischen Gebäude aus dem Jahr 1846 untergebracht ist. Mit seinen künstlichen Wasserfällen, Seen und dem botanischen Zentrum bietet der Park nicht nur Erholung, sondern auch Bildungsangebote zur lokalen Flora und Fauna. Die geschickte Gestaltung verbindet erhaltene Kolonialarchitektur mit avantgardistischen Strukturen und macht den Park zu einem beliebten Rückzugsort für Stadtbewohner und Touristen gleichermaßen.",
      hu: "A Hong Kong Park egy nyolchektáros zöld oázis Central sűrűn beépített felhőkarcolói között, amely kiválóan példázza a természet és a modern építészet összhangját. Az 1991-ben megnyitott park az egykori brit Victoria-laktanya területén fekszik, és több történelmi épületet is megőrzött az utókor számára. Egyik legnépszerűbb látványossága az Edward Youde madárház, amely a világ egyik legnagyobb, látogatók által bejárható röpdéje, ahol trópusi madarak élnek egy mesterséges völgyben. A park területén található a Flagstaff House Teatörténeti Múzeum is, amely Hongkong legrégebbi, 1846-ból származó gyarmati épületében kapott helyet. A mesterséges vízesésekkel, tavakkal és egy modern botanikai központtal kiegészülő kert nemcsak a kikapcsolódást szolgálja, hanem fontos természetvédelmi és oktatási szerepet is betölt a város szívében, kontrasztot alkotva a környező üvegpalotákkal.",
      ro: "Parcul Hong Kong este o oază de liniște de opt hectare situată printre zgârie-norii dens grupați din cartierul Central. Inaugurat în 1991 pe locul fostei cazărmi britanice Victoria, parcul este un exemplu remarcabil de integrare a naturii într-un peisaj urban modern. Una dintre atracțiile principale este Voliera Edward Youde, una dintre cele mai mari structuri de acest tip din lume, unde vizitatorii se pot plimba printr-o vale artificială ce recreează un ecosistem de pădure tropicală. În incinta parcului se află și Flagstaff House, sediul Muzeului Ceaiului, găzduit în cea mai veche clădire colonială din oraș, datând din 1846. Cu cascadele sale artificiale, iazurile cu pești și centrul botanic modern, parcul oferă un refugiu vital pentru locuitori și turiști. Designul său reușește să îmbine armonios elementele arhitecturale istorice cu facilitățile contemporane, promovând conservarea florei și faunei locale.",
      en: "Hong Kong Park is an eight-hectare sanctuary of greenery nestled amidst the dense skyscraper landscape of the Central district. Opened in 1991 on the site of the former British Victoria Barracks, the park is a prime example of successful urban design that integrates nature with modern architecture. A major highlight is the Edward Youde Aviary, one of the world's largest walk-through aviaries, built over an artificial valley that mimics a tropical rainforest canopy. The park also houses the Flagstaff House Museum of Tea Ware, located in a restored colonial building from 1846, the oldest of its kind in Hong Kong. Featuring artificial waterfalls, scenic ponds, and a modern botanical center, the park provides a much-needed respite from the urban hustle. Its clever layout preserves historical structures while introducing contemporary features, making it a key educational and recreational hub for understanding the region's diverse flora and birdlife.",
      es: "El Parque de Hong Kong se encuentra en el centro de Central, en la isla de Hong Kong, y es un oasis urbano de 8 hectáreas. Se inauguró en 1991 en el antiguo emplazamiento del Cuartel Victoria. El parque incluye un lago artificial, una cascada y un aviario con más de 300 aves. El Flagstaff House Museum de utensilios de té también se encuentra en el parque. Son especialmente populares la zona de juegos con pared de escalada y el área de fitness. El parque es un ejemplo de planificación urbana exitosa que une naturaleza y cultura.",
      pt: "O Parque de Hong Kong situa-se no centro de Central, na ilha de Hong Kong, e é um oásis urbano de 8 hectares. Foi inaugurado em 1991 no antigo local do Quartel Victoria. O parque inclui um lago artificial, uma cascata e um aviário com mais de 300 aves. O Flagstaff House Museum de utensílios de chá também se encontra no parque. O parque infantil com parede de escalada e a área de fitness são especialmente populares. O parque é um exemplo de planeamento urbano bem-sucedido, ligando a natureza e a cultura.",
      fr: "Le parc de Hong Kong se trouve au cœur de Central, sur l'île de Hong Kong, et constitue une oasis urbaine de 8 hectares. Ouvert en 1991, il occupe l'ancien site de la caserne Victoria. Le parc comprend un lac artificiel, une cascade et une volière abritant plus de 300 oiseaux. Le Flagstaff House Museum of Tea Ware est également situé dans le parc. L'aire de jeux avec mur d'escalade et l'espace fitness sont particulièrement appréciés. Le parc illustre un urbanisme réussi alliant nature et culture.",
    },
