      es: ["Superficie: 13,3 hectáreas", "Inauguración: 1970", "Número de esculturas en el jardín: 30", "Complejo de piscinas con 4 tanques", "El lago para aves alberga más de 200 ejemplares", "Visitantes anuales: más de 10 millones"],
