    parent: "HK",
    type: "park",
    name: { de: "Ma Wan Park", hu: "Ma Wan Park", ro: "Parcul Ma Wan", en: "Ma Wan Park" },
    coords: [114.062, 22.349],
    description: {
      de: "Ein Natur- und Themenpark auf der Insel Ma Wan, der Natur und Kunst vereint. Er ist bekannt für seine Skulpturengärten und die Arche Noah.",
      hu: "Természeti és vidámpark Ma Wan szigetén, amely ötvözi a természetet és a művészetet. Szoborkertjeiről és Noé bárkájáról ismert.",
      ro: "Un parc natural și tematic pe insula Ma Wan, îmbinând natura cu arta. Cunoscut pentru grădinile cu sculpturi și Arca lui Noe.",
      en: "A nature and theme park on Ma Wan Island that combines nature and art. It is known for its sculpture gardens and Noah's Ark.",
      es: "Un parque natural y temático en la isla de Ma Wan que combina naturaleza y arte. Es conocido por sus jardines de esculturas y el Arca de Noé.",
      pt: "Um parque natural e temático na ilha de Ma Wan que combina natureza e arte. É conhecido pelos seus jardins de esculturas e pela Arca de Noé.",
      fr: "Un parc naturel et thématique sur l'île de Ma Wan qui allie nature et art. Il est connu pour ses jardins de sculptures et son arche de Noé.",
    },
    facts: {
      de: ["Eröffnet im Jahr 2007", "Verfügt über einen Naturpfad", "Thema: Liebe und Harmonie", "Blick auf die Tsing-Ma-Brücke"],
      hu: ["2007-ben nyitották meg", "Tanösvénnyel rendelkezik", "Témája: szeretet és harmónia", "Kilátás a Tsing Ma hídra"],
      ro: ["Deschis în anul 2007", "Dispune de un traseu natural", "Tema: iubire și armonie", "Vedere spre podul Tsing Ma"],
      en: ["Opened in 2007", "Features a nature trail", "Theme: Love and Harmony", "Views of Tsing Ma Bridge"],
      es: ["Inaugurado en el año 2007", "Cuenta con un sendero natural", "Tema: Amor y Armonía", "Vistas al puente Tsing Ma"],
      pt: ["Inaugurado em 2007", "Possui um trilho natural", "Tema: Amor e Harmonia", "Vista para a Ponte Tsing Ma"],
      fr: ["Ouvert en 2007", "Dispose d'un sentier naturel", "Thème : Amour et Harmonie", "Vue sur le pont Tsing Ma"],
    },
    imageHint: "Ma Wan Park gardens and bridge view",
    descriptionAdvanced: {
      de: "Ma Wan Park ist eine grüne Oase auf der gleichnamigen Insel Ma Wan, die zwischen den Inseln Lantau und Tsing Yi liegt. Der im Jahr 2007 eröffnete Park verfolgt ein besonderes Konzept, das Natur, Kunst und Bildung unter dem Thema 'Liebe und Harmonie' vereint. Die bekannteste Attraktion des Geländes ist der lebensgroße Nachbau der Arche Noah, der nicht nur ein markantes Wahrzeichen ist, sondern auch Ausstellungen zu biblischen Themen und zum Umweltschutz beherbergt. Spaziergänger können den Naturpfad erkunden, der durch üppige Gärten und vorbei an kunstvollen Skulpturen führt, die die Schönheit der Schöpfung feiern. Ein Highlight für Fotografen ist der Panoramablick auf die imposante Tsing-Ma-Brücke, eine der längsten Hängebrücken der Welt, die direkt über die Insel führt. Der Park bietet zudem einen Solarturm zur Beobachtung der Sonne und dient als Ort der Ruhe und Reflexion abseits des hektischen Stadtlebens von Hongkong.",
      hu: "A Ma Wan Park egy különleges tematikus és szabadidőpark Ma Wan szigetén, amely Hongkong sűrűn beépített részei között kínál természetközeli kikapcsolódást. A 2007-ben átadott park alapgondolata a szeretet és a harmónia köré épül, ötvözve az oktatást a művészettel és a környezetvédelemmel. A park leglátványosabb eleme Noé bárkájának életnagyságú másolata, amelyben interaktív múzeum és szálloda is helyet kapott. A látogatók végigsétálhatnak a szoborkertekkel tarkított tanösvényeken, ahol a helyi növényvilág és különféle művészeti alkotások találkoznak. A park egyik legnépszerűbb pontja az a kilátóhely, ahonnan zavartalan kilátás nyílik a monumentális Tsing Ma hídra, amely Hongkong egyik mérnöki csodája. A park területén található napmegfigyelő torony és a különböző tematikus kertek nemcsak a családok számára kínálnak szórakozást, hanem fontos oktatási helyszínként is szolgálnak a fenntarthatóság és az emberi értékek népszerűsítésére.",
      ro: "Parcul Ma Wan este o destinație de agrement unică situată pe insula Ma Wan, oferind un refugiu liniștit între zonele urbane dense din Hong Kong. Deschis în 2007, parcul este conceput în jurul conceptului de promovare a dragostei, armoniei și respectului pentru natură. Piesa centrală a complexului este o replică la scară reală a Arcei lui Noe, care servește atât ca punct de reper vizual, cât și ca centru educațional cu expoziții multimedia despre mediu și viață. Traseele naturale ale parcului șerpuiesc prin grădini frumos amenajate, decorate cu sculpturi artistice care integrează elemente naturale. Un alt punct de interes major este vederea panoramică spectaculoasă asupra podului Tsing Ma, una dintre cele mai mari punți suspendate din lume, care trece chiar pe lângă insulă. Parcul include, de asemenea, un Turn Solar pentru observații astronomice și zone de meditație, fiind un loc ideal pentru familii și pentru cei care doresc să combine relaxarea în natură cu activități educative.",
      en: "Ma Wan Park is a sprawling green space on Ma Wan Island that blends environmental education with artistic expression. Established in 2007, the park is built upon the themes of 'Love and Harmony,' aiming to provide a serene escape from Hong Kong's urban sprawl. Its most famous feature is the world's first full-scale replica of Noah’s Ark, which houses interactive exhibits, a museum, and guest accommodation. The park’s Nature Garden features a winding trail that takes visitors through lush greenery, past unique sculptures, and toward a hilltop lookout. From this vantage point, visitors can enjoy unparalleled views of the Tsing Ma Bridge, an engineering marvel that spans the water nearby. With its combination of a solar tower for sun observation, botanical collections, and a focus on social values, Ma Wan Park serves as both a recreational area for families and an educational platform for sustainability and community harmony.",
      es: "Ma Wan Park se encuentra en la isla de Ma Wan, en los Nuevos Territorios. Fue inaugurado en 2010 y se extiende sobre 11,6 hectáreas. El parque es una reserva natural y ofrece senderos, una playa y un camping. El centro de visitantes informa sobre la ecología local y la historia de la isla. El parque también incluye un jardín chino y un parque temático llamado 'Noah's Ark', que muestra una réplica del Arca de Noé a escala 1:1. El parque es un destino popular para excursiones familiares.",
      pt: "O Ma Wan Park está localizado na ilha de Ma Wan, nos Novos Territórios. Foi inaugurado em 2010 e estende-se por 11,6 hectares. O parque é uma reserva natural e oferece trilhos para caminhadas, uma praia e um parque de campismo. O centro de visitantes informa sobre a ecologia local e a história da ilha. O parque inclui também um jardim chinês e um parque temático chamado 'Noah's Ark', que apresenta uma réplica da Arca de Noé em escala 1:1. O parque é um destino popular para passeios em família.",
      fr: "Le Ma Wan Park est situé sur l'île de Ma Wan, dans les Nouveaux Territoires. Il a ouvert ses portes en 2010 et s'étend sur 11,6 hectares. Le parc est une réserve naturelle et propose des sentiers de randonnée, une plage et un terrain de camping. Le centre de visiteurs informe sur l'écologie locale et l'histoire de l'île. Le parc comprend également un jardin chinois et un parc thématique nommé 'Noah's Ark', qui présente une réplique de l'Arche de Noé à l'échelle 1:1. Le parc est une destination prisée pour les excursions familiales.",
    },
