      en: ["Area: 11.6 hectares (28.7 acres)", "Opened: 2010", "Noah's Ark replica: 137 m (449 ft) long", "Beach length: 200 m (656 ft)", "Camping sites: 50", "Total cost: HK$1 billion"],
