      es: ["Superficie: aprox. 100 hectáreas", "Ubicación: Nuevos Territorios, cerca de Shenzhen", "Ruta migratoria: Asia Oriental-Australasia", "Especies de aves observadas: más de 200", "Antigua zona agrícola antes de 1990", "Profundidad media de los estanques: 1-2 metros"],
