      fr: ["Superficie : env. 100 hectares", "Surface rizicole : 30 hectares", "Nombre d'espèces d'oiseaux : plus de 200", "Statut : Réserve naturelle depuis 2004", "Altitude maximale : 10 mètres au-dessus du niveau de la mer", "Irrigation : systèmes de canaux traditionnels"],
