    imageHint: "Lung Fu Shan historic ruins in forest",
    descriptionAdvanced: {
      de: "Der im Jahr 1998 offiziell eingerichtete Lung Fu Shan Country Park ist mit einer Fläche von lediglich 47 Hektar der kleinste Landschaftspark in Hongkong. Trotz seiner geringen Größe ist er ökologisch von großer Bedeutung, da er an den Westhängen des Victoria Peak liegt und einen wichtigen Grünkorridor bildet. Ein historisches Highlight im Park sind die Ruinen der Pinewood Battery. Diese Küstenverteidigungsanlage wurde um 1903 erbaut und war während des Zweiten Weltkriegs heftigen Luftangriffen ausgesetzt; heute sind ihre Überreste ein geschütztes Denkmal. Neben der Geschichte bietet der Park eine bemerkenswerte Artenvielfalt: Er beherbergt über 100 Vogelarten und eine beeindruckende Population an Schmetterlingen, die in der dichten Vegetation ideale Lebensbedingungen finden. Wanderwege wie der Lung Fu Shan Fitness Trail führen durch schattige Wälder und bieten immer wieder Ausblicke auf die städtische Skyline und das Meer. Der Park dient als wichtiges Naherholungsgebiet für die Bewohner von Central und Western District und verbindet Naturerlebnis direkt mit der historischen Vergangenheit der Stadt.",
      hu: "Az 1998-ban létrehozott Lung Fu Shan Vidéki Park Hongkong legkisebb ilyen típusú természetvédelmi területe, mindössze 47 hektáron terül el. A Victoria-csúcs nyugati lejtőin elhelyezkedő park stratégiai elhelyezkedése miatt nemcsak ökológiai, hanem történelmi szempontból is kiemelkedő. Itt találhatók a Pinewood Battery romjai, amely egy 1903 körül épült tüzérségi állás volt, és fontos szerepet játszott a város védelmében a második világháború alatt. A terület ma a természet és a történelem különleges találkozóhelye: a buja növényzet fokozatosan visszahódítja a betonépítményeket. A park biodiverzitása lenyűgöző, több mint 100 madárfaj és számos ritka pillangófaj otthona, ami a város közelségéhez képest rendkívüli. A népszerű túraútvonalak, mint például a Lung Fu Shan fitneszösvény, árnyas erdőkön vezetnek keresztül, friss levegőt és nyugalmat biztosítva a sűrűn lakott városrészek lakóinak. A park kis mérete ellenére kulcsfontosságú szerepet tölt be a helyi ökoszisztémában és a környezeti nevelésben.",
      ro: "Înființat oficial în anul 1998, Parcul Lung Fu Shan este cel mai mic parc rural din Hong Kong, acoperind o suprafață de numai 47 de hectare. Situat pe versanții vestici ai faimosului Victoria Peak, parcul reprezintă o oază de biodiversitate și istorie situată la marginea metropolei. Principalul punct de interes istoric este Bateria Pinewood, o fortificație de coastă construită în jurul anului 1903, care a suferit daune majore în timpul raidurilor aeriene din cel de-al Doilea Război Mondial. Astăzi, ruinele acesteia sunt protejate și oferă o perspectivă fascinantă asupra trecutului militar al regiunii. Din punct de vedere ecologic, parcul este remarcabil pentru densitatea speciilor de fluturi și pentru cele peste 100 de specii de păsări care cuibăresc aici. Traseele de drumeție bine întreținute, cum este Lung Fu Shan Fitness Trail, sunt populare printre localnici pentru exerciții fizice și observarea naturii. Deși compact, parcul reușește să conserve un fragment vital de pădure subtropicală, oferind în același timp panorame spectaculoase spre cartierele rezidențiale din vest și spre portul Victoria.",
      en: "Established in 1998, Lung Fu Shan Country Park holds the distinction of being the smallest country park in Hong Kong, covering an area of just 47 hectares. Located on the western slopes of Victoria Peak, it serves as a crucial ecological link between the urban environment and the larger green belts of Hong Kong Island. The park's most significant historical feature is the ruins of the Pinewood Battery, a coastal defense installation built around 1903. This site was a key strategic point during World War II and faced heavy bombardment; today, the skeletal remains of the barracks and magazines are preserved as a heritage site. Despite its modest size, the park boasts a rich biodiversity, supporting over 100 species of birds and a vibrant population of butterflies. Lush vegetation and shaded paths, such as the Lung Fu Shan Fitness Trail, make it a favorite destination for hikers and nature enthusiasts seeking respite from the city. The park exemplifies the successful integration of historic preservation with urban nature conservation, providing vital habitats for local wildlife just minutes away from the Central District.",
      es: "El Lung Fu Shan Country Park se encuentra en el Lung Fu Shan (Montaña del Dragón y el Tigre), al oeste de la isla de Hong Kong. Fue designado como parque paisajístico en 1998 y abarca unas 113 hectáreas. El parque es conocido por sus bosques bien conservados y su abundancia de mariposas y aves. En la cima se encuentra un antiguo puesto de observación militar de la Segunda Guerra Mundial. El parque ofrece senderos con vistas al puerto de Victoria.",
      pt: "O Lung Fu Shan Country Park está localizado no Lung Fu Shan (Montanha do Dragão e do Tigre), no oeste da Ilha de Hong Kong. Foi designado como Country Park em 1998 e abrange uma área de cerca de 113 hectares. O parque é conhecido pelas suas florestas bem preservadas e pela riqueza de borboletas e aves. No topo encontra-se um antigo posto de observação militar da Segunda Guerra Mundial. O parque oferece trilhas com vista para o Porto de Victoria.",
      fr: "Le Lung Fu Shan Country Park est situé sur le Lung Fu Shan (montagne du Dragon et du Tigre) à l'ouest de l'île de Hong Kong. Classé parc rural en 1998, il s'étend sur environ 113 hectares. Le parc est réputé pour ses forêts bien préservées et sa richesse en papillons et en oiseaux. Au sommet se trouve un ancien poste d'observation militaire de la Seconde Guerre mondiale. Le parc propose des sentiers de randonnée avec vue sur le port de Victoria.",
    },
