    imageHint: "Clear Water Bay coastline and hills",
    descriptionAdvanced: {
      de: "Der Clear Water Bay Country Park liegt auf der östlichen Halbinsel Sai Kung in Hongkong und ist bekannt für seine dramatischen Klippen und weiten Küstenpanoramen. Seit seiner Gründung im Jahr 1979 bietet der Park eine wichtige Zuflucht vor der städtischen Hektik und ist ein Paradies für Outdoor-Aktivitäten. Das markanteste geografische Merkmal ist der High Junk Peak, dessen steile Silhouette zu den „drei scharfen Gipfeln“ von Hongkong gehört und anspruchsvolle Wanderwege bietet. In den flacheren Bereichen, wie der Clear Water Bay Kite Flying Area, nutzen Besucher die stetigen Meeresbrisen, um bunte Drachen steigen zu lassen, was zu einer lokalen Tradition geworden ist. Von den Aussichtspunkten blickt man direkt auf die zerklüfteten Ninepin Islands im Südchinesischen Meer. Der Park kombiniert natürliche Schönheit mit kulturellem Erbe, da sich der historische Tai Miu Tempel in unmittelbarer Nähe befindet. Die Mischung aus Wanderwegen, Picknickplätzen und spektakulären Meeresansichten macht ihn zu einem der beliebtesten Erholungsgebiete der Region.",
      hu: "A Clear Water Bay Vidéki Park Hongkong Sai Kung-félszigetének délkeleti részén fekszik, és a város egyik leglátványosabb természeti területe. Az 1979-ben alapított park híres meredek szikláiról és a Dél-kínai-tengerre nyíló végtelen kilátásról. A park legmagasabb pontja a High Junk Peak, amely éles formája miatt a túrázók körében Hongkong egyik legnépszerűbb csúcsa, bár megmászása némi tapasztalatot igényel. A terület ugyanakkor a családi kikapcsolódás központja is: a tágas füves lankákon virágzik a sárkányeregetés kultúrája, kihasználva a folyamatos tengeri szeleket. A kilátópontokról jól láthatóak a távolban fekvő Ninepin-szigetek különleges bazaltoszlopai. A park közvetlen közelében található a történelmi Tai Miu (Nagy Templom), amely Tin Hau istennőnek van szentelve, és a 13. század óta fontos zarándokhely. Ez a park tökéletesen ötvözi a drámai tájat, a sportolási lehetőségeket és a helyi spirituális hagyományokat.",
      ro: "Parcul Clear Water Bay, situat pe peninsula Sai Kung, este una dintre cele mai spectaculoase arii protejate din Hong Kong, renumit pentru relieful său de coastă accidentat și priveliștile marine vaste. Înființat în 1979, parcul este dominat de vârful ascuțit High Junk Peak, considerat unul dintre cele mai pitorești trasee de drumeție din regiune datorită profilului său dramatic pe linia orizontului. Zona este extrem de populară pentru înălțarea zmeielor, o activitate tradițională favorizată de vânturile constante care bat dinspre Marea Chinei de Sud. Vizitatorii se pot bucura de numeroase locuri de picnic și observatoare ce oferă panorame uluitoare spre insulele Ninepin și stâncile abrupte ale coastei. În apropiere se află templul Tai Miu, cel mai mare și mai vechi templu dedicat zeiței Tin Hau din Hong Kong, adăugând o dimensiune culturală importantă peisajului natural. Contrastul dintre apele azurii și dealurile verzi face din acest parc o destinație de evadare ideală din inima metropolei.",
      en: "Clear Water Bay Country Park is a stunning natural reserve located on the eastern reaches of Hong Kong's Sai Kung Peninsula, celebrated for its dramatic coastal scenery and rugged topography. Established in 1979, the park covers a diverse landscape ranging from the sharp, conical High Junk Peak—one of the city's most iconic hiking summits—to gentle, grassy plateaus overlooking the South China Sea. The park's Kite Flying Area is a local institution, where steady maritime breezes provide perfect conditions for enthusiasts of all ages. From the many vantage points, visitors can witness the striking basalt formations of the distant Ninepin Islands and the sheer cliffs that drop into the turquoise waters below. Adding to its appeal is the nearby Tai Miu, the oldest and largest Tin Hau Temple in Hong Kong, which dates back to the 13th century. This combination of challenging trails, scenic picnic spots, and profound historical significance makes it a premier destination for those seeking to explore the wilder side of Hong Kong.",
      es: "El Clear Water Bay Country Park se encuentra en la península de Clear Water Bay, en los Nuevos Territorios, y fue designado en 1979. Se extiende sobre una superficie de unas 600 hectáreas e incluye la playa de Clear Water Bay, una de las más limpias de Hong Kong. El parque es conocido por sus costas rocosas y su rica fauna marina. El sendero High Junk Peak atraviesa el parque y ofrece vistas impresionantes de la bahía. La zona también es conocida por su marisco fresco.",
      pt: "O Clear Water Bay Country Park está localizado na península de Clear Water Bay, nos Novos Territórios, e foi designado em 1979. Estende-se por uma área de cerca de 600 hectares e inclui a praia de Clear Water Bay, uma das praias mais limpas de Hong Kong. O parque é conhecido pelas suas costas rochosas e pela rica fauna marinha. A trilha High Junk Peak atravessa o parque e oferece vistas deslumbrantes sobre a baía. A área também é conhecida pelos seus frutos do mar frescos.",
      fr: "Le Clear Water Bay Country Park est situé sur la péninsule de Clear Water Bay dans les Nouveaux Territoires et a été classé en 1979. Il s'étend sur une superficie d'environ 600 hectares et comprend la plage de Clear Water Bay, l'une des plus propres de Hong Kong. Le parc est réputé pour ses côtes rocheuses et sa riche faune marine. Le sentier de randonnée High Junk Peak traverse le parc, offrant des vues imprenables sur la baie. La région est également connue pour ses fruits de mer frais.",
    },
